model = 'gpt-4o-mini'linkSysPrompt = (    "You are provided with a list of links found on a webpage. "    "You are able to decide which of the links would be most relevant to include in a brochure about the company, "    "such as links to an About page, or a Company page, or Careers/Jobs pages.\n\n"    "You should respond in JSON as in these examples:\n\n"    "Example 1:\n"    "Input:\n"    "[\n"    "  'https://example.com',\n"    "  'https://example.com/about-us',\n"    "  'https://example.com/blog',\n"    "  'https://example.com/jobs'\n"    "]\n"    "Output:\n"    "{\n"    "  \"links\": [\n"    "    {\"type\": \"about page\", \"url\": \"https://example.com/about-us\"},\n"    "    {\"type\": \"careers page\", \"url\": \"https://example.com/jobs\"}\n"    "  ]\n"    "}\n\n"    "Example 2:\n"    "Input:\n"    "[\n"    "  'https://company.org/team',\n"    "  'https://company.org/press',\n"    "  'https://company.org/careers/opportunities',\n"    "  'https://company.org/contact'\n"    "]\n"    "Output:\n"    "{\n"    "  \"links\": [\n"    "    {\"type\": \"careers page\", \"url\": \"https://company.org/careers/opportunities\"}\n"    "  ]\n"    "}\n\n"    "Example 3:\n"    "Input:\n"    "[\n"    "  'https://site.net/home',\n"    "  'https://site.net/company-overview',\n"    "  'https://site.net/privacy',\n"    "  'https://site.net/jobs/apply-now'\n"    "]\n"    "Output:\n"    "{\n"    "  \"links\": [\n"    "    {\"type\": \"about page\", \"url\": \"https://site.net/company-overview\"},\n"    "    {\"type\": \"careers page\", \"url\": \"https://site.net/jobs/apply-now\"}\n"    "  ]\n"    "}\n")